# Helper for structured reading of values from a RustBuffer.
class RustBufferStream

  def initialize(rbuf)
    @rbuf = rbuf
    @offset = 0
  end

  def remaining
    @rbuf.len - @offset
  end

  def read(size)
    raise InternalError, 'read past end of rust buffer' if @offset + size > @rbuf.len

    data = @rbuf.data.get_bytes @offset, size

    @offset += size

    data
  end

  def readU64
    unpack_from 8, 'Q>'
  end

  def readF32
    unpack_from 4, 'g'
  end

  def readF64
    unpack_from 8, 'G'
  end

  def readBool
    v = unpack_from 1, 'c'

    return false if v == 0
    return true if v == 1

    raise InternalError, 'Unexpected byte for Boolean type'
  end

  def readString
    size = unpack_from 4, 'l>'

    raise InternalError, 'Unexpected negative string length' if size.negative?

    read(size).force_encoding(Encoding::UTF_8)
  end

  def readBytes
    size = unpack_from 4, 'l>'

    raise InternalError, 'Unexpected negative byte string length' if size.negative?

    read(size).force_encoding(Encoding::BINARY)
  end

  # The Object type CompiledDocument.

  def readTypeCompiledDocument
    handle = unpack_from 8, 'Q>'
    return CompiledDocument.uniffi_allocate(handle)
  end

  # The Object type Template.

  def readTypeTemplate
    handle = unpack_from 8, 'Q>'
    return Template.uniffi_allocate(handle)
  end

  # The Record type BlobInput.

  def readTypeBlobInput
    BlobInput.new(
      data: readBytes,
      metadata: readString
    )
  end

  # The Record type ExportOnceResult.

  def readTypeExportOnceResult
    ExportOnceResult.new(
      bytes: readBytes,
      warnings: readOptionalstring
    )
  end

  # The Record type PageRange.

  def readTypePageRange
    PageRange.new(
      start: readOptionalu64,
      _end: readOptionalu64
    )
  end

  # The Record type PageSize.

  def readTypePageSize
    PageSize.new(
      width: readF64,
      height: readF64
    )
  end

  # The Record type RegisteredFont.

  def readTypeRegisteredFont
    RegisteredFont.new(
      family: readString,
      path: readOptionalstring
    )
  end

  # The Record type ZipLimits.

  def readTypeZipLimits
    ZipLimits.new(
      max_entries: readOptionalu64,
      max_total_decompressed_bytes: readOptionalu64
    )
  end

  
  
  # The Enum type CompilationMode.

  def readTypeCompilationMode
    variant = unpack_from 4, 'l>'
    
    if variant == 1
      return CompilationMode::DEVELOPMENT
    end
    if variant == 2
      return CompilationMode::PRODUCTION
    end

    raise InternalError, 'Unexpected variant tag for TypeCompilationMode'
  end

  

  
  
  # The Enum type DiagnosticColor.

  def readTypeDiagnosticColor
    variant = unpack_from 4, 'l>'
    
    if variant == 1
      return DiagnosticColor::NONE
    end
    if variant == 2
      return DiagnosticColor::ANSI
    end

    raise InternalError, 'Unexpected variant tag for TypeDiagnosticColor'
