# Helper for structured writing of values into a RustBuffer.
class RustBufferBuilder
  def initialize
    @rust_buf = RustBuffer.alloc 16
    @rust_buf.len = 0
  end

  def finalize
    rbuf = @rust_buf

    @rust_buf = nil

    rbuf
  end

  def discard
    return if @rust_buf.nil?

    rbuf = finalize
    rbuf.free
  end

  def write(value)
    reserve(value.bytes.size) do
      @rust_buf.data.put_array_of_char @rust_buf.len, value.bytes
    end
  end

  def write_U64(v)
    v = OicanaUniffi::uniffi_in_range(v, "u64", 0, 2**64)
    pack_into(8, 'Q>', v)
  end

  def write_F32(v)
    pack_into(4, 'g', v)
  end

  def write_F64(v)
    pack_into(8, 'G', v)
  end

  def write_Bool(v)
    pack_into(1, 'c', v ? 1 : 0)
  end

  def write_String(v)
    v = OicanaUniffi::uniffi_utf8(v)
    pack_into 4, 'l>', v.bytes.size
    write v
  end

  def write_Bytes(v)
    v = OicanaUniffi::uniffi_bytes(v)
    pack_into 4, 'l>', v.bytes.size
    write v
  end

  # The Object type CompiledDocument.

  def write_TypeCompiledDocument(obj)
    handle = CompiledDocument.uniffi_lower obj
    pack_into(8, 'Q>', handle)
  end

  # The Object type Template.

  def write_TypeTemplate(obj)
    handle = Template.uniffi_lower obj
    pack_into(8, 'Q>', handle)
  end

  # The Record type BlobInput.

  def write_TypeBlobInput(v)
    self.write_Bytes(v.data)
    self.write_String(v.metadata)
  end

  # The Record type ExportOnceResult.

  def write_TypeExportOnceResult(v)
    self.write_Bytes(v.bytes)
    self.write_Optionalstring(v.warnings)
  end

  # The Record type PageRange.

  def write_TypePageRange(v)
    self.write_Optionalu64(v.start)
    self.write_Optionalu64(v._end)
  end

  # The Record type PageSize.

  def write_TypePageSize(v)
    self.write_F64(v.width)
    self.write_F64(v.height)
  end

  # The Record type RegisteredFont.

