      pack_into(1, 'c', 1)
      self.write_TypeZipLimits(v)
    end
  end

  # The Sequence<T> type for string.

  def write_Sequencestring(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_String(item)
    end
  end

  # The Sequence<T> type for bytes.

  def write_Sequencebytes(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_Bytes(item)
    end
  end

  # The Sequence<T> type for TypePageSize.

  def write_SequenceTypePageSize(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_TypePageSize(item)
    end
  end

  # The Sequence<T> type for TypeRegisteredFont.

  def write_SequenceTypeRegisteredFont(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_TypeRegisteredFont(item)
    end
  end

  # The Map<T> type for string.

  def write_MapStringString(items)
    pack_into(4, 'l>', items.size)

    items.each do |k, v|
      write_String(k)
      self.write_String(v)
    end
  end# The Map<T> type for TypeBlobInput.

  def write_MapStringTypeBlobInput(items)
    pack_into(4, 'l>', items.size)

    items.each do |k, v|
      write_String(k)
      self.write_TypeBlobInput(v)
    end
  end

  private

  def reserve(num_bytes)
    if @rust_buf.len + num_bytes > @rust_buf.capacity
      @rust_buf = RustBuffer.reserve(@rust_buf, num_bytes)
    end

    yield

    @rust_buf.len += num_bytes
  end

  def pack_into(size, format, value)
    reserve(size) do
      @rust_buf.data.put_array_of_char @rust_buf.len, [value].pack(format).bytes
    end
  end
end

