      "ExportFormat::PDF()"
    end

    def ==(other)
      if !other.pdf?
        return false
      end

      true
    end

    # For each variant, we have an `NAME?` method for easily checking
    # whether an instance is that variant.
    
    def pdf?
      instance_of? ExportFormat::PDF
    end
    
    def png?
      instance_of? ExportFormat::PNG
    end
    
    def svg?
      instance_of? ExportFormat::SVG
    end
    
  end
