      "ExportFormat::PNG(pixels_per_pt=#{@pixels_per_pt})"
    end

    def ==(other)
      if !other.png?
        return false
      end
      if @pixels_per_pt != other.pixels_per_pt
        return false
      end

      true
    end

    # For each variant, we have an `NAME?` method for easily checking
    # whether an instance is that variant.
    
