    RustBuffer.check_lower_MapStringString(json_inputs)
    
    blob_inputs = blob_inputs.each.with_object({}) { |(k, v), res| res[OicanaUniffi::uniffi_utf8(k)] = v }
    RustBuffer.check_lower_MapStringTypeBlobInput(blob_inputs)
    
    mode = mode
    RustBuffer.check_lower_TypeCompilationMode(mode)
    
    format = format
    RustBuffer.check_lower_TypeExportFormat(format)
    
    pages = (pages ? pages : nil)
    RustBuffer.check_lower_OptionalTypePageRange(pages)
    
    limits = (limits ? limits : nil)
    RustBuffer.check_lower_OptionalTypeZipLimits(limits)
    
  result = OicanaUniffi.rust_call_with_error(OicanaError,:uniffi_oicana_uniffi_fn_func_export_once,RustBuffer.allocFromBytes(files),RustBuffer.alloc_from_MapStringString(json_inputs),RustBuffer.alloc_from_MapStringTypeBlobInput(blob_inputs),RustBuffer.alloc_from_TypeCompilationMode(mode),RustBuffer.alloc_from_TypeExportFormat(format),RustBuffer.alloc_from_OptionalTypePageRange(pages),RustBuffer.alloc_from_OptionalTypeZipLimits(limits))
  return result.consumeIntoTypeExportOnceResult
end


  
  

