  class CompiledDocument

  # A private helper for initializing instances of the class from a raw handle,
  # bypassing any initialization logic and ensuring they are GC'd properly.
  def self.uniffi_allocate(handle)
    inst = allocate
    inst.instance_variable_set :@handle, handle
    ObjectSpace.define_finalizer(inst, uniffi_define_finalizer_by_handle(handle, inst.object_id))
    return inst
  end

  # A private helper for registering an object finalizer.
  # N.B. it's important that this does not capture a reference
  # to the actual instance, only its underlying handle.
  def self.uniffi_define_finalizer_by_handle(handle, object_id)
    Proc.new do |_id|
      OicanaUniffi.rust_call(
        :uniffi_oicana_uniffi_fn_free_compileddocument,
        handle
      )
    end
  end

  # A private helper for lowering instances into a raw handle.
  # This does an explicit typecheck, because accidentally lowering a different type of
  # object in a place where this type is expected, could lead to memory unsafety.
  def self.uniffi_check_lower(inst)
    if not inst.is_a? self
      raise TypeError.new "Expected a CompiledDocument instance, got #{inst}"
    end
  end

  def uniffi_clone_handle()
    return OicanaUniffi.rust_call(
      :uniffi_oicana_uniffi_fn_clone_compileddocument,
      @handle
    )
  end

  def self.uniffi_lower(inst)
    return inst.uniffi_clone_handle()
  end

  

  def export(format, pages = nil)
        format = format
        RustBuffer.check_lower_TypeExportFormat(format)
        pages = (pages ? pages : nil)
        RustBuffer.check_lower_OptionalTypePageRange(pages)
    result = OicanaUniffi.rust_call_with_error(OicanaError,:uniffi_oicana_uniffi_fn_method_compileddocument_export,uniffi_clone_handle(),RustBuffer.alloc_from_TypeExportFormat(format),RustBuffer.alloc_from_OptionalTypePageRange(pages))
    return result.consumeIntoBytes
  end
  def pages()
    result = OicanaUniffi.rust_call(:uniffi_oicana_uniffi_fn_method_compileddocument_pages,uniffi_clone_handle(),)
    return result.consumeIntoSequenceTypePageSize
  end
  def warnings()
    result = OicanaUniffi.rust_call(:uniffi_oicana_uniffi_fn_method_compileddocument_warnings,uniffi_clone_handle(),)
    return result.consumeIntoOptionalstring
  end
  
